char *reverseString(char *s) {
    int n = strlen(s);
    char *res = (char *)malloc((n + 1) * sizeof(char));

    int j = 0;

    // Traverse on s in backward direction
    // and add each character to a new string
    for (int i = n - 1; i >= 0; i--) {
        res[j] = s[i];
        j++;
    }

    // Null-terminate the result string
    res[n] = '\0';
    return res;
}

