OutputefcdbaUsing Two Pointers - O(n) Time and O(1) SpaceStart from both ends of the string and keep swapping characters while moving toward the center. Each swap places the correct character in its reversed position, and when both pointers meet in the middle, the entire string becomes reversed.
            C++

    #include <iostream>
using namespace std;

string reverseString(string &s) {
    int left = 0, right = s.length() - 1;

    // Swap characters from both ends till we reach
    // the middle of the string
    while (left < right) {
        swap(s[left], s[right]);
        left++;
        right--;
    }

    return s;
}

int main() {
    string s = "abdcfe";
    cout << reverseString(s);
    return 0;
}


