Using Stack - O(n) Time and O(n) SpaceThe idea is to use stack for reversing a string because Stack follows Last In First Out (LIFO) principle. This means the last character you add is the first one you'll take out. So, when we push all the characters of a string into the stack, the last character becomes the first one to pop. 
            C++

    #include <iostream>
using namespace std;

string reverseString(string &s) {
    stack<char> st;

    // Push the charcters into stack
    for (int i = 0; i < s.size(); i++) {
        st.push(s[i]);
    }

    // Pop the characters of stack into the original string
    for (int i = 0; i < s.size(); i++) {
        s[i] = st.top();
        st.pop();
    }

  	return s;
}

int main() {
    string s = "abdcfe";
    cout << reverseString(s);
    return 0;
}


            C

    #include <stdio.h>
#include <string.h>

void reverseString(char s[])
{
    int n = strlen(s);
    char stack[n]; // Stack implemented as array
    int top = -1;

    // Push characters onto the stack
    for (int i = 0; i < n; i++)
    {
        stack[++top] = s[i];
    }

    // Pop characters from stack back into the string
    for (int i = 0; i < n; i++)
    {
        s[i] = stack[top--];
    }
}

int main()
{
    char s[] = "abdcfe";
    reverseString(s);
    printf("%s\n", s);
    return 0;
}


