    // Create an array to hold the reversed characters
    const res = new Array(s.length);

    // Pop the characters of the stack and store in the array
    for (let i = 0; i < s.length; i++) {
        res[i] = stack.pop();
    }

    // Join the array to form the reversed string
    return res.join('');
}

